  // Technique detail info
  'techniques.box.detail': '\u064A\u0633\u062A\u062E\u062F\u0645\u0647 \u0623\u0641\u0631\u0627\u062F Navy SEALs \u0644\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u062A\u0648\u062A\u0631. \u0645\u0631\u0627\u062D\u0644 \u0645\u062A\u0633\u0627\u0648\u064A\u0629 \u0645\u0646 \u0627\u0644\u0634\u0647\u064A\u0642 \u0648\u0627\u0644\u062D\u0628\u0633 \u0648\u0627\u0644\u0632\u0641\u064A\u0631 \u0648\u0627\u0644\u062D\u0628\u0633 \u062A\u062E\u0644\u0642 \u0625\u064A\u0642\u0627\u0639\u0627\u064B \u0645\u0647\u062F\u0626\u0627\u064B \u064A\u0642\u0644\u0644 \u0627\u0644\u0643\u0648\u0631\u062A\u064A\u0632\u0648\u0644 \u0648\u064A\u062D\u0633\u0646 \u0627\u0644\u062A\u0631\u0643\u064A\u0632.',
  'techniques.fourSevenEight.detail': '\u0637\u0648\u0631\u0647 \u0627\u0644\u062F\u0643\u062A\u0648\u0631 \u0623\u0646\u062F\u0631\u0648 \u0648\u064A\u0644. \u0627\u0644\u0632\u0641\u064A\u0631 \u0627\u0644\u0645\u0645\u062A\u062F \u064A\u0646\u0634\u0637 \u0627\u0644\u062C\u0647\u0627\u0632 \u0627\u0644\u0639\u0635\u0628\u064A \u0646\u0638\u064A\u0631 \u0627\u0644\u0648\u062F\u064A\u060C \u0645\u0645\u0627 \u064A\u062C\u0639\u0644\u0647 \u0645\u062B\u0627\u0644\u064A\u0627\u064B \u0644\u0644\u0646\u0648\u0645 \u0641\u064A \u062F\u0642\u0627\u0626\u0642.',
  'techniques.physioSigh.detail': '\u0627\u0643\u062A\u0634\u0641\u0647 \u0639\u0627\u0644\u0645 \u0627\u0644\u0623\u0639\u0635\u0627\u0628 \u0641\u064A \u0633\u062A\u0627\u0646\u0641\u0648\u0631\u062F \u0627\u0644\u062F\u0643\u062A\u0648\u0631 \u0623\u0646\u062F\u0631\u0648 \u0647\u0648\u0628\u0631\u0645\u0627\u0646. \u0634\u0647\u064A\u0642 \u0645\u0632\u062F\u0648\u062C \u064A\u062A\u0628\u0639\u0647 \u0632\u0641\u064A\u0631 \u0637\u0648\u064A\u0644 \u0647\u0648 \u0623\u0633\u0631\u0639 \u0637\u0631\u064A\u0642\u0629 \u0644\u062A\u0642\u0644\u064A\u0644 \u0627\u0644\u062A\u0648\u062A\u0631 \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0627\u0644\u0641\u0639\u0644\u064A.',
  'techniques.coherence.detail': '\u0627\u0644\u062A\u0646\u0641\u0633 \u0628\u0645\u0639\u062F\u0644 5.5 \u0623\u0646\u0641\u0627\u0633 \u0641\u064A \u0627\u0644\u062F\u0642\u064A\u0642\u0629 \u064A\u0632\u0627\u0645\u0646 \u0645\u0639\u062F\u0644 \u0636\u0631\u0628\u0627\u062A \u0627\u0644\u0642\u0644\u0628 \u0648\u0636\u063A\u0637 \u0627\u0644\u062F\u0645 \u0648\u0627\u0644\u062C\u0647\u0627\u0632 \u0627\u0644\u0639\u0635\u0628\u064A \u2014 \u0644\u064A\u062D\u0642\u0642 \u062D\u0627\u0644\u0629 \u062A\u0633\u0645\u0649 "\u0627\u0644\u062A\u0648\u0627\u0641\u0642" \u0644\u0623\u0641\u0636\u0644 \u062A\u0628\u0627\u064A\u0646 \u0641\u064A \u0645\u0639\u062F\u0644 \u0636\u0631\u0628\u0627\u062A \u0627\u0644\u0642\u0644\u0628.',
  'techniques.triangle.detail': '\u0646\u0645\u0637 \u0644\u0637\u064A\u0641 \u0645\u0646 3 \u0645\u0631\u0627\u062D\u0644 \u0645\u062B\u0627\u0644\u064A \u0644\u0644\u0645\u0628\u062A\u062F\u0626\u064A\u0646. \u064A\u0648\u0627\u0632\u0646 \u0627\u0644\u062C\u0647\u0627\u0632 \u0627\u0644\u0639\u0635\u0628\u064A \u062F\u0648\u0646 \u062D\u0628\u0633 \u0627\u0644\u0646\u0641\u0633\u060C \u0645\u0645\u0627 \u064A\u062C\u0639\u0644\u0647 \u0633\u0647\u0644\u0627\u064B \u0648\u0645\u062A\u0627\u062D\u0627\u064B \u0644\u0644\u062C\u0645\u064A\u0639.',
  'techniques.power.detail': '\u0645\u0633\u062A\u0648\u062D\u0649 \u0645\u0646 \u0637\u0631\u064A\u0642\u0629 \u0641\u064A\u0645 \u0647\u0648\u0641. \u0627\u0644\u062A\u0646\u0641\u0633 \u0627\u0644\u0633\u0631\u064A\u0639 \u064A\u0644\u064A\u0647 \u062D\u0628\u0633 \u0627\u0644\u0646\u0641\u0633 \u064A\u0632\u064A\u062F \u0627\u0644\u0637\u0627\u0642\u0629 \u0648\u064A\u0642\u0644\u0648\u064A \u0627\u0644\u062F\u0645 \u0648\u064A\u0639\u0632\u0632 \u0627\u0644\u0627\u0633\u062A\u062C\u0627\u0628\u0629 \u0627\u0644\u0645\u0646\u0627\u0639\u064A\u0629.',
  'techniques.fourFourSixTwo.detail': '\u0627\u0644\u0632\u0641\u064A\u0631 \u0627\u0644\u0645\u0645\u062A\u062F (6 \u062B) \u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u0627\u0644\u0634\u0647\u064A\u0642 (4 \u062B) \u064A\u0646\u0642\u0644 \u0627\u0644\u062C\u0633\u0645 \u0625\u0644\u0649 \u0627\u0633\u062A\u0631\u062E\u0627\u0621 \u0639\u0645\u064A\u0642. \u0627\u0644\u062A\u0648\u0642\u0641 \u0627\u0644\u0642\u0635\u064A\u0631 \u0628\u064A\u0646 \u0627\u0644\u062F\u0648\u0631\u0627\u062A \u064A\u0639\u064A\u062F \u0636\u0628\u0637 \u0625\u064A\u0642\u0627\u0639 \u0627\u0644\u062A\u0646\u0641\u0633.',
  'techniques.kapalabhati.detail': '\u062A\u0642\u0646\u064A\u0629 \u064A\u0648\u063A\u064A\u0629 \u0642\u062F\u064A\u0645\u0629 \u062A\u0639\u0646\u064A "\u0646\u0641\u0633 \u0627\u0644\u062C\u0645\u062C\u0645\u0629 \u0627\u0644\u0645\u0636\u064A\u0626\u0629". \u0632\u0641\u064A\u0631 \u0633\u0631\u064A\u0639 \u0648\u0642\u0648\u064A \u064A\u0646\u0634\u0637 \u0627\u0644\u062C\u0633\u0645 \u0648\u064A\u0635\u0641\u064A \u0627\u0644\u0630\u0647\u0646 \u0648\u064A\u0642\u0648\u064A \u0627\u0644\u062D\u062C\u0627\u0628 \u0627\u0644\u062D\u0627\u062C\u0632.',
  'techniques.twoToOne.detail': '\u0627\u0644\u0632\u0641\u064A\u0631 \u0636\u0639\u0641 \u0637\u0648\u0644 \u0627\u0644\u0634\u0647\u064A\u0642\u060C \u0645\u0645\u0627 \u064A\u0632\u064A\u062F \u0637\u0631\u062F CO\u2082 \u0648\u064A\u0646\u0634\u0637 \u0627\u0644\u0639\u0635\u0628 \u0627\u0644\u0645\u0628\u0647\u0645. \u0623\u062D\u062F \u0623\u0643\u062B\u0631 \u0627\u0644\u0623\u0646\u0645\u0627\u0637 \u0641\u0639\u0627\u0644\u064A\u0629 \u0644\u0644\u0627\u0633\u062A\u0631\u062E\u0627\u0621 \u0627\u0644\u0639\u0645\u064A\u0642.',
  'techniques.cyclicSigh.detail': '\u0623\u0638\u0647\u0631\u062A \u062F\u0631\u0627\u0633\u0629 \u0633\u062A\u0627\u0646\u0641\u0648\u0631\u062F \u0623\u0646 5 \u062F\u0642\u0627\u0626\u0642 \u0645\u0646 \u0627\u0644\u062A\u0646\u0647\u062F \u0627\u0644\u062F\u0648\u0631\u064A \u0623\u0643\u062B\u0631 \u0641\u0639\u0627\u0644\u064A\u0629 \u0641\u064A \u062A\u0642\u0644\u064A\u0644 \u0627\u0644\u062A\u0648\u062A\u0631 \u0645\u0646 \u0627\u0644\u062A\u0623\u0645\u0644. \u0634\u0647\u064A\u0642 \u0645\u0632\u062F\u0648\u062C + \u0632\u0641\u064A\u0631 \u0645\u0645\u062A\u062F \u064A\u0639\u064A\u062F \u0636\u0628\u0637 \u0627\u0644\u062C\u0647\u0627\u0632 \u0627\u0644\u0639\u0635\u0628\u064A.',

